import re, os, sys
root = sys.argv[1]
seeds = sys.argv[2:]
pat = re.compile(r'''(?:import|export)\s[^;]*?from\s+["']([^"']+)["']|import\s*\(\s*["']([^"']+)["']\s*\)|import\s+["']([^"']+)["']|new URL\(\s*["']([^"']+)["']''', re.S)
seen, ext, stack = set(), set(), list(seeds)
def resolve(base, spec):
    if spec.startswith('@/'): p = os.path.join(root, spec[2:])
    elif spec.startswith('.'): p = os.path.normpath(os.path.join(os.path.dirname(base), spec))
    else: return None
    for c in [p, p+'.ts', p+'.tsx', p+'/index.ts', p+'.json']:
        if os.path.isfile(c): return c
    if p.endswith('.js') and os.path.isfile(p[:-3]+'.ts'): return p[:-3]+'.ts'
    print("UNRESOLVED", base, spec, file=sys.stderr); return None
while stack:
    f = os.path.normpath(stack.pop())
    if f in seen: continue
    seen.add(f)
    if not f.endswith(('.ts','.tsx')): continue
    src = open(f).read()
    for m in pat.finditer(src):
        spec = next(g for g in m.groups() if g)
        r = resolve(f, spec)
        if r: stack.append(r)
        elif not spec.startswith(('.','@/')): ext.add(spec.split('/')[0] if not spec.startswith('@') else '/'.join(spec.split('/')[:2]))
for f in sorted(seen): print(os.path.relpath(f, root))
print("EXT:", sorted(ext), file=sys.stderr)
EOF
